<script setup lang="ts">
import { computed, ref } from 'vue'
import type { AiImportRecord } from '../domain/ai'
import type { KnowledgePoint, ResourceItem } from '../domain/types'
import Icon from './Icon.vue'
const props = defineProps<{ records: AiImportRecord[]; points: KnowledgePoint[]; resources: ResourceItem[]; loading: boolean; error: string }>()
const emit = defineEmits<{ create: []; refresh: []; update: [record: AiImportRecord]; locate: [id: string] }>()
const selectedId = ref('')
const selected = computed(() => props.records.find(r => r.id === selectedId.value) || props.records[0])
function date(value: string | number) { const timestamp = typeof value === 'number' ? value * 1000 : Number.isNaN(Number(value)) ? value : Number(value) * 1000; return new Intl.DateTimeFormat('zh-CN', {year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit', timeZone:'Asia/Shanghai'}).format(new Date(timestamp)) }
</script>
<template><section class="ai-records-workspace glass-panel" aria-label="导入记录"><header class="ai-records-heading"><div><h1>导入记录 <span>{{records.length}}</span></h1></div><div><button class="button" :disabled="loading" @click="emit('refresh')">重新读取</button><button class="button button-primary" @click="emit('create')"><Icon name="plus" :size="16" />整理新文本</button></div></header><p v-if="error" class="ai-error" role="alert">{{error}}</p><p v-if="loading" class="ai-task-status" role="status"><span class="spinner small" />正在读取导入记录</p><div v-else-if="!records.length" class="ai-records-empty"><Icon name="clock" :size="32" /><h2>还没有已采用的知识</h2><p>整理并保存学习笔记后，可在这里查看知识和来源。</p><button class="button" @click="emit('create')">整理学习文本</button></div><div v-else class="ai-records-layout"><nav class="ai-record-list" aria-label="已采用记录"><button v-for="record in records" :key="record.id" :class="{selected:record.id===selected?.id}" @click="selectedId=record.id"><Icon name="check" :size="17" /><span><strong>{{record.sourceName}}</strong><small>{{date(record.createdAt)}}</small><small>新增 {{record.added}} · 更新 {{record.updated}} · 复用 {{record.reused}}</small></span></button></nav><section v-if="selected" class="ai-record-details"><h2>{{selected.sourceName}}</h2><p class="ai-help">{{date(selected.createdAt)}} 保存到本机</p><dl><div><dt>新增知识点</dt><dd>{{selected.added}}</dd></div><div><dt>更新知识点</dt><dd>{{selected.updated}}</dd></div><div><dt>复用知识点</dt><dd>{{selected.reused}}</dd></div></dl><h3>本次关联知识</h3><div class="ai-record-contributions"><button v-for="id in selected.pointIds" :key="id" class="button" :disabled="!points.some(p=>p.id===id)" @click="emit('locate',id)"><Icon name="file" :size="15" />{{points.find(p=>p.id===id)?.name || '知识点已移除'}}</button><p v-if="!selected.pointIds.length" class="ai-help">没有关联知识点。</p></div><h3>来源资料</h3><p>{{selected.sourceResourceIds.map(id=>resources.find(r=>r.id===id)?.title || '资料已移除').join('、') || '未关联资料'}}</p><p class="ai-help">更新时请重新提供文本；未提及的已有知识和关联会保留。</p><button class="button button-primary" data-testid="ai-record-update" @click="emit('update',selected)">更新这次记录</button></section></div></section></template>
<style scoped>.ai-records-workspace{margin:8px 16px 16px;flex:1;min-height:0;display:flex;flex-direction:column;padding:26px 30px;overflow:auto}.ai-records-heading{display:flex;align-items:center;justify-content:space-between;gap:20px;padding-bottom:22px;border-bottom:1px solid #d9d9d9}.ai-records-heading h1{font-size:25px;font-weight:600}.ai-records-heading h1 span{font-size:14px;font-weight:400;color:#646464;margin-left:9px}.ai-records-heading p{font-size:13px;color:#646464;margin-top:9px}.ai-records-heading>div:last-child{display:flex;gap:10px}.ai-records-empty{display:flex;flex-direction:column;align-items:center;text-align:center;gap:18px;padding:70px 20px;color:#646464}.ai-records-empty h2{font-size:18px;font-weight:500;color:#333}.ai-records-empty p{line-height:1.8}.ai-records-layout{display:grid;grid-template-columns:minmax(260px,.75fr) minmax(0,1.4fr);gap:30px;margin-top:24px}.ai-record-list{min-width:0}.ai-record-list button{display:flex;align-items:flex-start;gap:13px;text-align:left;width:100%;padding:17px 14px;border-radius:8px;border-bottom:1px solid #ddd}.ai-record-list button.selected{background:#e8e8e8}.ai-record-list strong{font-size:14px;font-weight:600;overflow-wrap:anywhere}.ai-record-list small{display:block;font-size:13px;color:#646464;margin-top:7px}.ai-record-details{min-width:0;line-height:1.8;padding:18px 22px;background:#ffffff7a;border:1px solid #d4d4d4;border-radius:10px}.ai-record-details h2{font-size:19px;overflow-wrap:anywhere}.ai-record-details h3{font-size:14px;font-weight:600;margin:25px 0 12px}.ai-record-details p{font-size:13px;overflow-wrap:anywhere}.ai-record-details dl{display:flex;gap:40px;margin:23px 0}.ai-record-details dt{font-size:13px;color:#646464}.ai-record-details dd{margin:4px 0 0;font-size:23px;font-variant-numeric:tabular-nums}.ai-record-contributions{display:flex;flex-wrap:wrap;gap:8px}.ai-record-details>.button{margin-top:12px}@media(max-width:850px){.ai-records-layout{grid-template-columns:1fr}.ai-records-heading{flex-wrap:wrap}.ai-records-workspace{padding:22px}}
</style>
